//! Each backend op against NumPy values (engine/tests/fixtures/ops.json, generated by
//! ref/gen_op_fixtures.py). The same checks run on every backend.

use engine::backend::cpu::Cpu;
use engine::backend::{AttentionShape, Backend, Weight};
use engine::gguf::TensorType;
use serde_json::Value;

/// |got - want| <= TOL * max(1, |want|)
const TOL: f32 = 1e-5;

const WEIGHT_TYPES: [(&str, TensorType); 4] = [
    ("f32", TensorType::F32),
    ("bf16", TensorType::BF16),
    ("q8_0", TensorType::Q8_0),
    ("q4_0", TensorType::Q4_0),
];

fn floats(v: &Value) -> Vec<f32> {
    let values = v.as_array().unwrap().iter();
    values.map(|x| x.as_f64().unwrap() as f32).collect()
}

fn int(v: &Value) -> usize {
    v.as_u64().unwrap() as usize
}

fn assert_close(name: &str, got: &[f32], want: &Value) {
    let want = floats(want);
    assert_eq!(got.len(), want.len(), "{name}");
    for (i, (g, w)) in got.iter().zip(&want).enumerate() {
        assert!(
            (g - w).abs() <= TOL * w.abs().max(1.0),
            "{name} index {i}: got {g}, want {w}"
        );
    }
}

/// Weight bytes copied into 8-byte aligned storage, like tensors in a GGUF file (which start
/// on 32-byte boundaries).
fn aligned(v: &Value) -> Vec<u64> {
    let bytes = v.as_array().unwrap();
    let mut storage = vec![0u64; bytes.len() / 8 + 1];
    for (i, byte) in bytes.iter().enumerate() {
        storage[i / 8] |= byte.as_u64().unwrap() << (i % 8 * 8); // little-endian
    }
    storage
}

fn bytes_of<'a>(storage: &'a [u64], v: &Value) -> &'a [u8] {
    let len = v.as_array().unwrap().len();
    // SAFETY: `storage` holds at least `len` initialized bytes.
    unsafe { std::slice::from_raw_parts(storage.as_ptr().cast::<u8>(), len) }
}

fn check_ops<B: Backend>(b: &B) {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/ops.json");
    let fx: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let up = |v: &Value| b.upload(&floats(v));

    for (kind, ty) in WEIGHT_TYPES {
        // matmul: a batch of 3 tokens; matvec: one token, rows not a multiple of 4;
        // matmul_tiled: 35 tokens and 70 rows, enough for several partly filled tiles.
        for op in ["matmul", "matvec", "matmul_tiled"] {
            let f = &fx[format!("{op}_{kind}")];
            let storage = aligned(&f["weight_bytes"]);
            let (rows, cols) = (int(&f["rows"]), int(&f["cols"]));
            let w = b.weights(Weight {
                ty,
                rows,
                cols,
                data: bytes_of(&storage, &f["weight_bytes"]),
            });
            let mut out = b.alloc(floats(&f["x"]).len() / cols * rows);
            b.matmul(&w, &up(&f["x"]), &mut out);
            assert_close(&format!("{op}_{kind}"), &b.read(&out), &f["out"]);
        }

        let f = &fx[format!("embed_{kind}")];
        let storage = aligned(&f["weight_bytes"]);
        let (rows, cols) = (int(&f["rows"]), int(&f["cols"]));
        let w = b.weights(Weight {
            ty,
            rows,
            cols,
            data: bytes_of(&storage, &f["weight_bytes"]),
        });
        let tokens: Vec<u32> = (f["tokens"].as_array().unwrap().iter())
            .map(|t| t.as_u64().unwrap() as u32)
            .collect();
        let mut out = b.alloc(tokens.len() * cols);
        b.embed(&w, &tokens, &mut out);
        // Decoding is exact: a bit shift for BF16, a small integer times an f16 otherwise.
        assert_eq!(b.read(&out), floats(&f["out"]), "embed_{kind}");
    }

    for name in ["rms_norm", "rms_norm_wide"] {
        let f = &fx[name];
        let mut out = b.alloc(floats(&f["x"]).len());
        let eps = f["eps"].as_f64().unwrap() as f32;
        b.rms_norm(&up(&f["x"]), &up(&f["weight"]), eps, &mut out);
        assert_close(name, &b.read(&out), &f["out"]);
    }

    let f = &fx["rope"];
    let mut x = up(&f["x"]);
    let base = f["freq_base"].as_f64().unwrap() as f32;
    b.rope(
        &mut x,
        int(&f["n"]),
        int(&f["head_dim"]),
        int(&f["pos"]),
        base,
    );
    assert_close("rope", &b.read(&x), &f["out"]);

    let f = &fx["attention"];
    let shape = AttentionShape {
        pos: int(&f["pos"]),
        n_head: int(&f["n_head"]),
        n_head_kv: int(&f["n_head_kv"]),
        head_dim: int(&f["head_dim"]),
    };
    let (mut k_cache, mut v_cache) = (up(&f["k_cache"]), up(&f["v_cache"]));
    let mut out = b.alloc(floats(&f["q"]).len());
    b.attention(
        shape,
        &up(&f["q"]),
        &up(&f["k"]),
        &up(&f["v"]),
        &mut k_cache,
        &mut v_cache,
        &mut out,
    );
    let got = b.read(&out);
    assert!(got.iter().all(|v| v.is_finite()), "attention overflowed");
    assert_close("attention", &got, &f["out"]);
    assert_eq!(b.read(&k_cache), floats(&f["k_cache_after"]), "k cache");
    assert_eq!(b.read(&v_cache), floats(&f["v_cache_after"]), "v cache");

    let f = &fx["silu_mul"];
    let mut out = b.alloc(floats(&f["gate"]).len());
    b.silu_mul(&up(&f["gate"]), &up(&f["up"]), &mut out);
    assert_close("silu_mul", &b.read(&out), &f["out"]);

    let f = &fx["add"];
    let mut x = up(&f["x"]);
    b.add(&mut x, &up(&f["y"]));
    assert_close("add", &b.read(&x), &f["out"]);

    // slice is a view of part of a buffer
    let whole = up(&fx["add"]["x"]);
    let want = &floats(&fx["add"]["x"])[3..8];
    assert_eq!(b.read(&b.slice(&whole, 3, 5)), want, "slice");
}

#[test]
fn cpu() {
    check_ops(&Cpu);
}

#[cfg(target_os = "macos")]
#[test]
fn metal() {
    check_ops(&engine::backend::metal::Metal::new().unwrap());
}
